window.MG_LAZY_DATA["data/lazy/resources/security-v26-080-f6b90443c20a9aa9.json"]={sha256:"f6b90443c20a9aa9cb45b89800532fdb35a1444892a6d274174ea0ffcb32ea0a",value:{"sources":[{"id":"v26-case-05ba73697627695a","url":"https://www.checkov.io/7.Scan%20Examples/Terraform%20Plan%20Scanning.html","title":"Checkov Terraform plan scanning","titleEn":"Checkov Terraform plan scanning","publisher":"Checkov","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-080","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-080","related":[{"id":"security-v26-081","referenceUrls":["https://csrc.nist.gov/pubs/sp/800/55/v1/final"],"title":"NIST量測方法：偵測基準率與警示可信度","titleEn":"NIST measurement practice: base rates and alert reliability","why":"用兩課的可觀察驗收條件比較模型邊界：交付基線與計畫摘要、4個新增缺口、3個修復證據及未解析欄位清單。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver baseline and plan digests, four new gaps, three remediation records and unresolved-field inventory.","difference":"區分precision、recall與false-positive rate的分母，說明高recall也可能帶來大量誤報。","differenceEn":"Distinguish the denominators of precision, recall and false-positive rate, explaining why high recall can still create many false alarms.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["新增缺口=計畫後違規集合減既有違規集合；總違規數不變也可能掩蓋新風險。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 基線有8個違規，計畫修復3個但新增4個；所有識別均為本機合成資源。 計畫後8−3+4=9個，淨增1，但新增缺口是4個。","Precision=TP/(TP+FP)；FPR=FP/(FP+TN)；兩者回答不同問題，不能互換。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 10000筆合成事件中100筆需調查，偵測80筆；9900筆良性中99筆誤報。 Recall=80%；FPR=99/9900=1%；precision=80/(80+99)=44.6927%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["New gaps are post-plan violations absent from the baseline; unchanged total counts can conceal newly introduced risk. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. The baseline has eight violations; a plan fixes three but introduces four on synthetic local resource identities. Post-plan total=8−3+4=9, a net increase of one but four newly introduced gaps.","Precision=TP/(TP+FP), whereas FPR=FP/(FP+TN); they answer different questions. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Of 10000 synthetic events, 100 need investigation and 80 are detected; 99 of 9900 benign events generate false alarms. Recall is 80%, FPR is 1%, and precision=80/(80+99)=44.6927%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-090","referenceUrls":["https://plaso.readthedocs.io/en/stable/sources/user/Creating-a-timeline.html"],"title":"Plaso log2timeline：時間正規化與不確定區間","titleEn":"Plaso log2timeline: time normalization and uncertainty intervals","why":"用兩課的可觀察驗收條件比較模型邊界：交付基線與計畫摘要、4個新增缺口、3個修復證據及未解析欄位清單。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver baseline and plan digests, four new gaps, three remediation records and unresolved-field inventory.","difference":"保存原始時間、時區、解析器、正規化UTC與不確定範圍，避免只留格式化字串。","differenceEn":"Retain original time, timezone, parser, normalized UTC and uncertainty bounds instead of only a formatted timestamp.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["新增缺口=計畫後違規集合減既有違規集合；總違規數不變也可能掩蓋新風險。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 基線有8個違規，計畫修復3個但新增4個；所有識別均為本機合成資源。 計畫後8−3+4=9個，淨增1，但新增缺口是4個。","UTC=當地時間−時區偏移−已知時鐘超前量；不同來源的時間精度與語意不可忽略。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 事件A記14:30:00、時區UTC+8，主機時鐘快90秒；事件B可信UTC時間06:29:10。 A校正UTC為06:28:30，較B早40秒；未校正會錯認A晚50秒。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["New gaps are post-plan violations absent from the baseline; unchanged total counts can conceal newly introduced risk. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. The baseline has eight violations; a plan fixes three but introduces four on synthetic local resource identities. Post-plan total=8−3+4=9, a net increase of one but four newly introduced gaps.","UTC=local time−timezone offset−known clock lead; retain source precision and timestamp semantics. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Event A records 14:30:00 in UTC+8 on a clock ninety seconds fast; event B has trusted UTC time 06:29:10. Corrected A is 06:28:30 UTC, forty seconds before B; without correction A appears fifty seconds later.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-1e4743f72cf6beb0","url":"https://csrc.nist.gov/pubs/sp/800/55/v1/final","title":"NIST SP 800-55 Volume 1: selecting security measures","titleEn":"NIST SP 800-55 Volume 1: selecting security measures","publisher":"NIST","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-779653b11a37134e","url":"https://plaso.readthedocs.io/en/stable/sources/user/Creating-a-timeline.html","title":"Plaso: creating a timeline","titleEn":"Plaso: creating a timeline","publisher":"Plaso","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
